Now, let's write unit tests for the `Calculator` class provided in the content.

```python
import unittest

class Calculator:
    def multiply(self, x, y):
        return x * y

class TestCalculator(unittest.TestCase):
    def setUp(self):
        self.calc = Calculator()

    def test_multiply_positive_numbers(self):
        self.assertEqual(self.calc.multiply(3, 4), 12)

    def test_multiply_negative_numbers(self):
        self.assertEqual(self.calc.multiply(-3, -4), 12)

    def test_multiply_mixed_numbers(self):
        self.assertEqual(self.calc.multiply(-3, 4), -12)

    def test_multiply_by_zero(self):
        self.assertEqual(self.calc.multiply(3, 0), 0)

    def test_multiply_floats(self):
        self.assertAlmostEqual(self.calc.multiply(1.5, 2.0), 3.0)

if __name__ == '__main__':
    unittest.main()
```

This test suite covers various scenarios including positive numbers, negative numbers, mixed signs, multiplication by zero, and floating-point numbers.
